let postData = JSONSerialization.data(withJSONObject: parameters, options: [])

let request = NSMutableURLRequest(url: NSURL(string: "https://api.frame.io/v4/accounts/63aae2e5-b376-4ec3-bae6-ed6f635fad72/users/312d7d3a-b284-4d9f-aef0-1f60a19ea87b")! as URL,
