package main

import (
	"fmt"
	"strings"
	"net/http"
	"io"
)

func main() {

	url := "https://api.frame.io/v4/accounts/78a09d26-dbcd-4a77-9ea2-167a991da7f6/files/1cc5d214-c463-40b3-8be0-747afae534ea/comments"

	payload := strings.NewReader("{
  "data": {
    "text": "This is great!",
    "anchor": {
      "x": 0.5,
      "y": 0.5
    },
    "annotation": "[{\"tool\":\"rect\",\"color\":\"#F22237\",\"size\":8,\"x\":0.277726001863933,\"y\":0.12909555568499534,\"w\":0.3153168321877913,\"h\":0.5308131407269339,\"ix\":0.277726001863933,\"iy\":0.12909555568499534,\"radius\":8}]",
    "attachments": [
      {
        "file_size": 1024000,
        "media_type": "image/png",
        "name": "screenshot.png"
      }
    ],
    "completed": false,
    "duration": 10,
    "links": [
      {
        "end_index": 13,
        "start_index": 5,
        "url": "https://www.example.com"
      }
    ],
    "page": 4,
    "text_review_annotation": {
      "bounds": [
        {
          "height": 42,
          "width": 130,
          "x": 12.5,
          "y": 24
        }
      ],
      "selection_text": "existing copy",
      "suggested_text": "updated copy",
      "text_review_annotation_type": "replace"
    },
    "timestamp": "00:00:02:12"
  }
}")

	req, _ := http.NewRequest("POST", url, payload)

	req.Header.Add("Authorization", "Bearer <token>")
	req.Header.Add("Content-Type", "application/json")

	res, _ := http.DefaultClient.Do(req)

	defer res.Body.Close()
	body, _ := io.ReadAll(res.Body)

	fmt.Println(res)
	fmt.Println(string(body))

}

